import { memo, useCallback } from "react";
import { useTheme } from "@mui/material/styles";
import IconButton from "@mui/material/IconButton";
import CircularProgress from "@mui/material/CircularProgress";

import { CloseIcon } from "assets/images";
import { globalThemes } from "theme";
import { Theme } from "utils/constants";

import * as S from "./styled";

type InputProps = {
  value: string;
  isLoading: boolean;
  onChange: (value: string) => void;
};

const Input = ({ value, isLoading, onChange }: InputProps) => {
  const theme = useTheme();

  const handleChange = useCallback(
    (event: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
      onChange(event.target.value);
    },
    [onChange]
  );

  const handleClear = useCallback(() => {
    onChange("");
  }, [onChange]);

  return (
    <S.CustomPaper
      style={{
        border:
          theme.palette.mode === Theme.Light
            ? globalThemes.border.light
            : globalThemes.border.dark,
      }}
    >
      <S.CustomInputBase
        placeholder="Enter GitHub username, i.e. gaearon"
        inputProps={{ "aria-label": "search github name" }}
        value={value}
        onChange={handleChange}
      />
      {value && !isLoading && (
        <IconButton aria-label="search" onClick={handleClear}>
          <CloseIcon style={{ color: theme.palette.text.secondary }} />
        </IconButton>
      )}
      {isLoading && (
        <IconButton>
          <CircularProgress
            size={18}
            sx={{
              color: theme.palette.text.secondary,
            }}
          />
        </IconButton>
      )}
    </S.CustomPaper>
  );
};

export default memo(Input);
