import { memo, useEffect, useState, useCallback } from "react";
import { useSearchParams } from "react-router-dom";
import { useTheme } from "@mui/material/styles";

import Input from "components/Input";
import { searchByUsername, clearSearch } from "stores/actions/search";
import { useTypedSelector, useTypedDispatch } from "stores/store";
import { PER_PAGE, DEFAULT_PAGE } from "utils/constants";

import * as S from "./styled";
import SearchResults from "./components/SearchResults";

const SearchPage = () => {
  const theme = useTheme();

  let [searchParams, setSearchParams] = useSearchParams();

  const dispatch = useTypedDispatch();

  const [keyword, setKeyword] = useState("");
  const [page, setPage] = useState(DEFAULT_PAGE);

  const { isLoading, data } = useTypedSelector((state) => state.searchState);

  const handleSearchChange = useCallback(
    (value: string) => {
      setKeyword(value);
      setSearchParams({ q: value });
    },
    [setKeyword, setSearchParams]
  );

  const handlePageChange = useCallback(
    (event: React.ChangeEvent<unknown>, page: number) => {
      setPage(page);
      setSearchParams({ q: keyword, page: page.toString() });
    },
    [keyword, setPage, setSearchParams]
  );

  useEffect(() => {
    let delayDebounceFn = setTimeout(() => {});

    const q = searchParams.get("q");
    const page = Number(searchParams.get("page")) || DEFAULT_PAGE;

    if (q) {
      delayDebounceFn = setTimeout(() => {
        dispatch(searchByUsername({ q, page, per_page: PER_PAGE }));
        setKeyword(q);
        setPage(page);
      }, 200);
    } else {
      setSearchParams({});
      dispatch(clearSearch());
      setKeyword("");
      setPage(DEFAULT_PAGE);
    }
    return () => clearTimeout(delayDebounceFn);
  }, [searchParams, setSearchParams, dispatch]);

  return (
    <S.Search>
      <Input
        value={keyword}
        onChange={handleSearchChange}
        isLoading={isLoading}
      />
      {data ? (
        <SearchResults
          page={page}
          results={data}
          keyword={keyword}
          onChange={handlePageChange}
        />
      ) : (
        <S.EmptySearch>
          <S.Logo>
            <S.CustomGitHubMark
              style={{ color: theme.palette.text.secondary }}
            />
            <S.CustomGitHubLogo
              style={{ color: theme.palette.text.secondary }}
            />
          </S.Logo>
          <S.Desc
            style={{
              color: theme.palette.text.secondary,
            }}
          >
            Enter GitHub username and search users matching the input like
            Google Search, click avatars to view more details, including
            repositories, followers and following.
          </S.Desc>
        </S.EmptySearch>
      )}
    </S.Search>
  );
};

export default memo(SearchPage);
