import { memo, useMemo } from "react";
import { useTheme } from "@mui/material/styles";
import Pagination from "@mui/material/Pagination";

import UserItem from "components/UserItem";
import { SearchIcon } from "assets/images";
import { User, SearchResultsType } from "utils/types";
import {
  MAX_COUNT_PAGINATION,
  MAX_USERS_RESPONSE,
  PER_PAGE,
  DEFAULT_PAGE,
} from "utils/constants";

import * as S from "./styled";

type SearchResultsProps = {
  page: number;
  results: SearchResultsType;
  keyword: string;
  onChange: (event: React.ChangeEvent<unknown>, page: number) => void;
};

const SearchResults = ({
  page,
  results,
  keyword,
  onChange,
}: SearchResultsProps) => {
  const theme = useTheme();

  const { total_count: totalCount, items: users } = results;

  const [isIncompleteData, count] = useMemo(
    () => [
      totalCount > MAX_USERS_RESPONSE,
      totalCount > MAX_USERS_RESPONSE
        ? MAX_COUNT_PAGINATION
        : Math.ceil(totalCount / PER_PAGE),
    ],
    [totalCount]
  );

  if (!totalCount)
    return (
      <S.Empty>
        <SearchIcon style={{ color: theme.palette.text.secondary }} />
        <S.EmptyMsg style={{ color: theme.palette.text.primary }}>
          No search result found for <b>{keyword}</b>
        </S.EmptyMsg>
      </S.Empty>
    );

  return (
    <S.SearchResults>
      <S.Main>
        <S.TotalLabel style={{ color: theme.palette.text.primary }}>
          {totalCount} GitHub user(s) found
          {isIncompleteData &&
            " (only the first 1000 search results are available)"}
        </S.TotalLabel>
        <S.UserList>
          {users?.map((user: User) => (
            <UserItem key={user.login} user={user} defaultFavorite={false} />
          ))}
        </S.UserList>
      </S.Main>
      {count > DEFAULT_PAGE && (
        <S.PagWrapper>
          <Pagination
            count={count}
            page={page}
            onChange={onChange}
            variant="outlined"
            shape="rounded"
          />
        </S.PagWrapper>
      )}
    </S.SearchResults>
  );
};

export default memo(SearchResults);
