import apiService from "./APIService";
import { FavoriteParams } from "./types/favorite";

const followAUser = (params: FavoriteParams) => {
  return apiService.request("PUT /user/following/" + params.username);
};

const unFollowAUser = (params: FavoriteParams) => {
  return apiService.request("DELETE /user/following/" + params.username);
};

const getFollowingUsers = () => {
  return apiService.request("GET /user/following");
};

export { followAUser, unFollowAUser, getFollowingUsers };
