import { Dispatch } from "redux";

import { searchByUsernameRequest } from "services/SearchService";
import { SearchParams } from "services/types/search";

import * as types from "./../types/search";

const searching = (dispatch: Dispatch) => {
  dispatch({
    type: types.SEARCHING,
    payload: true,
  });
};

export const searchByUsername =
  (params: SearchParams) => async (dispatch: Dispatch) => {
    try {
      searching(dispatch);

      const { data } = await searchByUsernameRequest(params);

      dispatch({ type: types.SEARCH_BY_USERNAME, payload: data });
    } catch (error) {
      return Promise.reject(error);
    }
  };

export const clearSearch = () => {
  return {
    type: types.RESET_SEARCH,
  };
};
